import React from "react";

export default function OrbitRight() {
  return (
    <div className="stage">

      {/* CENTER AVATAR */}
      <div className="center-avatar">
        <img
          src="https://i.ibb.co/4f1R9Zc/female-avatar.png"
          alt="avatar"
        />
        <p>Swetha A</p>
      </div>

      {/* ORBIT SYSTEM */}
      <div className="orbit-ring">

        <div className="node n1">React</div>
        <div className="node n2">Java</div>
        <div className="node n3">Spring Boot</div>
        <div className="node n4">MySQL</div>
        <div className="node n5">UI/UX</div>

      </div>

      <style>{`

        /* =========================
           STAGE (HUB CONTAINER)
        ========================== */
        .stage {
          position: relative;
          width: 380px;
          height: 380px;
          margin: auto;

          display: flex;
          justify-content: center;
          align-items: center;
        }

        /* =========================
           CENTER AVATAR (HUB)
        ========================== */
        .center-avatar {
          position: absolute;
          z-index: 10;
          text-align: center;
        }

        .center-avatar img {
          width: 110px;
          height: 110px;
          border-radius: 50%;

          object-fit: cover;

          border: 2px solid rgba(56,189,248,0.5);
          box-shadow: 0 0 25px rgba(56,189,248,0.25);
        }

        .center-avatar p {
          margin-top: 8px;
          font-size: 12px;
          color: #94a3b8;
        }

        /* =========================
           ORBIT RING (SPINNING FRAME)
        ========================== */
        .orbit-ring {
          position: absolute;
          width: 100%;
          height: 100%;

          animation: spin 14s linear infinite;
          transform-origin: center;
        }

        @keyframes spin {
          from { transform: rotate(0deg); }
          to { transform: rotate(360deg); }
        }

        /* =========================
           NODE BASE STYLE (GLASSMORPHISM)
        ========================== */
        .node {
          position: absolute;

          padding: 8px 14px;
          border-radius: 18px;

          font-size: 11px;
          color: #cbd5e1;
          white-space: nowrap;

          background: rgba(255,255,255,0.05);
          border: 1px solid rgba(255,255,255,0.12);
          backdrop-filter: blur(10px);

          box-shadow: 0 0 12px rgba(56,189,248,0.08);

          /* IMPORTANT: keep text upright */
          transform-origin: center;
        }

        /* =========================
           ORBIT POSITIONING (5 NODES → 72° spacing)
        ========================== */

        /* top */
        .n1 {
          top: 5%;
          left: 50%;
          transform: translateX(-50%) rotate(0deg);
        }

        /* right top */
        .n2 {
          top: 28%;
          right: 6%;
          transform: rotate(72deg);
        }

        /* bottom right */
        .n3 {
          bottom: 5%;
          right: 25%;
          transform: rotate(144deg);
        }

        /* bottom left */
        .n4 {
          bottom: 5%;
          left: 25%;
          transform: rotate(216deg);
        }

        /* left top */
        .n5 {
          top: 28%;
          left: 6%;
          transform: rotate(288deg);
        }

        /* =========================
           OPTIONAL: subtle glow ring
        ========================== */
        .stage::before {
          content: "";
          position: absolute;
          width: 320px;
          height: 320px;
          border-radius: 50%;

          border: 1px solid rgba(56,189,248,0.12);
          box-shadow: 0 0 40px rgba(56,189,248,0.08);

          z-index: 0;
        }

        /* =========================
           HOVER MICRO INTERACTION
        ========================== */
        .node:hover {
          transform: scale(1.05);
          border-color: rgba(56,189,248,0.4);
          box-shadow: 0 0 18px rgba(56,189,248,0.2);
        }

      `}</style>

    </div>
  );
}
